#include <vector>
#include <algorithm>

struct Person {
    std::string name;
    int age;
};

void sortPeople(std::vector<Person>& people) {
    std::sort(people.begin(), people.end(), [](const Person& a, const Person& b) {
        return a.age < b.age;
    });
}

#include <memory>

class Resource {
public:
    void doSomething() {}
};

void useResource() {
    std::unique_ptr<Resource> res = std::make_unique<Resource>();
    res->doSomething();
    // Automatically deleted when 'res' goes out of scope
}

template <typename T>
class Singleton {
public:
    static T& getInstance() {
        static T instance;
        return instance;
    }
protected:
    Singleton() = default;
    ~Singleton() = default;
private:
    Singleton(const Singleton&) = delete;
    Singleton& operator=(const Singleton&) = delete;
};

#include <fstream>
#include <string>

class FileHandler {
    std::fstream file;
public:
    FileHandler(const std::string& filename) : file(filename, std::ios::in | std::ios::out) {}
    ~FileHandler() {
        if (file.is_open()) file.close();
    }
    std::fstream& get() { return file; }
};

#include <sstream>
#include <vector>
#include <string>

std::vector<std::string> split(const std::string& s, char delimiter) {
    std::vector<std::string> tokens;
    std::string token;
    std::istringstream tokenStream(s);
    while (std::getline(tokenStream, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}
